#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
    vector<vector<int>> tree;
    long maxScore = 0;
    int count = 0;

public:
    int countHighestScoreNodes(vector<int>& parents) {
        int n = parents.size();
        tree.resize(n);
        for (int i = 1; i < n; ++i)
            tree[parents[i]].push_back(i);
        dfs(0, n);
        return count;
    }

    int dfs(int node, int total) {
        long score = 1;
        int size = 0;
        for (int child : tree[node]) {
            int t = dfs(child, total);
            score *= t;
            size += t;
        }
        if (node != 0)
            score *= (total - size - 1);
        if (score == maxScore) ++count;
        else if (score > maxScore) {
            maxScore = score;
            count = 1;
        }
        return size + 1;
    }
};
